/// The non-abstract class stored under a proxy id. Like the designer, a later
/// definition replaces an earlier one with the same proxy id.
pub fn class_by_proxy(proxy: u32) -> Option<&'static ClassDef> {
    if proxy == 0 {
        return None;
    }
    CLASSES
        .iter()
        .rev()
        .find(|c| !c.is_abstract && !c.is_struct && c.proxy == proxy)
}

pub fn class_by_name(name: &str) -> Option<&'static ClassDef> {
    // Designer lookups are case insensitive and later definitions win.
    CLASSES
        .iter()
        .rev()
        .find(|c| c.name.eq_ignore_ascii_case(name))
}

impl ClassDef {
    /// Property definition for an id, searching this class and then its bases.
    pub fn prop(&self, id: u32) -> Option<&'static PropDef> {
        let mut class: Option<&'static ClassDef> = class_by_name(self.name);
        while let Some(c) = class {
            if let Some(p) = c.props.iter().rev().find(|p| p.id == id) {
                return Some(p);
            }
            class = if c.base.is_empty() {
                None
            } else {
                class_by_name(c.base)
            };
        }
        None
    }

    /// Whether this class is `name` or derives from it.
    pub fn is_a(&self, name: &str) -> bool {
        let mut class: Option<&'static ClassDef> = class_by_name(self.name);
        while let Some(c) = class {
            if c.name.eq_ignore_ascii_case(name) {
                return true;
            }
            class = if c.base.is_empty() {
                None
            } else {
                class_by_name(c.base)
            };
        }
        false
    }
}

/// Display name of a class proxy id for diagnostics.
pub fn class_name(proxy: u32) -> String {
    class_by_proxy(proxy)
        .map(|c| c.name.to_string())
        .unwrap_or_else(|| format!("0x{proxy:08X}"))
}

/// Display name of a property id of a class for diagnostics.
pub fn prop_name(proxy: u32, id: u32) -> String {
    class_by_proxy(proxy)
        .and_then(|c| c.prop(id))
        .map(|p| p.name.to_string())
        .unwrap_or_else(|| format!("0x{id:08X}"))
}

